
CREATE TABLE saas_plans(id text PRIMARY KEY,code text NOT NULL,name text NOT NULL,version integer NOT NULL CHECK(version>=1),price_minor integer NOT NULL DEFAULT 0 CHECK(price_minor>=0),period_days integer NOT NULL DEFAULT 30 CHECK(period_days BETWEEN 1 AND 365),location_limit integer NOT NULL DEFAULT 1 CHECK(location_limit>=1),staff_limit integer NOT NULL DEFAULT 20 CHECK(staff_limit>=1),table_limit integer NOT NULL DEFAULT 100 CHECK(table_limit>=1),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX saas_plan_version_unique ON saas_plans(code,version);
CREATE TABLE saas_subscriptions(tenant_id text PRIMARY KEY REFERENCES tenants(id),plan_id text NOT NULL REFERENCES saas_plans(id),status text NOT NULL DEFAULT 'trial' CHECK(status IN ('trial','active','grace','suspended')),trial_ends_at timestamptz,paid_until timestamptz,grace_ends_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE saas_invoices(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),plan_id text NOT NULL REFERENCES saas_plans(id),number text NOT NULL UNIQUE,period_start timestamptz NOT NULL,period_end timestamptz NOT NULL,amount_minor integer NOT NULL CHECK(amount_minor>=0),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','issued','paid','voided')),due_at timestamptz NOT NULL,issued_at timestamptz,paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(period_end>period_start));
CREATE INDEX saas_invoice_tenant_idx ON saas_invoices(tenant_id,created_at);
CREATE TABLE saas_payment_claims(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),invoice_id text NOT NULL REFERENCES saas_invoices(id),reference text NOT NULL,method text NOT NULL CHECK(method IN ('cash','bank_transfer','mobile_money')),amount_minor integer NOT NULL CHECK(amount_minor>0),proof_note text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','rejected')),submitted_by text NOT NULL REFERENCES "user"(id),reviewed_by text REFERENCES "user"(id),reviewed_at timestamptz,review_reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX saas_payment_queue_idx ON saas_payment_claims(status,created_at);
CREATE INDEX saas_payment_invoice_idx ON saas_payment_claims(invoice_id);
CREATE UNIQUE INDEX saas_verified_reference_unique ON saas_payment_claims(lower(reference)) WHERE status='verified';
CREATE TABLE saas_support_tickets(id text PRIMARY KEY,tenant_id text REFERENCES tenants(id),category text NOT NULL CHECK(category IN ('billing','technical','account')),priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','urgent')),subject text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved','closed')),opened_by text NOT NULL REFERENCES "user"(id),assigned_to text REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX saas_tickets_queue_idx ON saas_support_tickets(status,created_at);
CREATE INDEX saas_tickets_tenant_idx ON saas_support_tickets(tenant_id,created_at);
CREATE TABLE saas_ticket_messages(id text PRIMARY KEY,ticket_id text NOT NULL REFERENCES saas_support_tickets(id),sender_id text NOT NULL REFERENCES "user"(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX saas_messages_ticket_idx ON saas_ticket_messages(ticket_id,created_at);
CREATE TABLE saas_support_grants(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),requested_by text NOT NULL REFERENCES "user"(id),approved_by text REFERENCES "user"(id),scope text NOT NULL DEFAULT 'metadata' CHECK(scope='metadata'),reason text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','revoked','rejected')),expires_at timestamptz,approved_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX saas_grants_tenant_idx ON saas_support_grants(tenant_id,status,created_at);
CREATE TABLE saas_platform_settings(id text PRIMARY KEY DEFAULT 'default' CHECK(id='default'),trial_days integer NOT NULL DEFAULT 14 CHECK(trial_days BETWEEN 1 AND 90),grace_days integer NOT NULL DEFAULT 7 CHECK(grace_days BETWEEN 0 AND 30),support_contact text NOT NULL DEFAULT '',incident_banner text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO saas_platform_settings(id) VALUES('default') ON CONFLICT DO NOTHING;
INSERT INTO saas_plans(id,code,name,version,price_minor,period_days,location_limit,staff_limit,table_limit,active) VALUES('starter-v1','starter','Starter',1,0,30,1,50,250,true) ON CONFLICT(id) DO NOTHING;
INSERT INTO saas_subscriptions(tenant_id,plan_id,status,trial_ends_at,paid_until)
 SELECT t.id,'starter-v1',CASE WHEN t.status='suspended' THEN 'suspended' WHEN t.status='trial' THEN 'trial' ELSE 'active' END,tr.expires_at,CASE WHEN t.status='active' THEN now()+interval '30 days' ELSE NULL END
 FROM tenants t LEFT JOIN tenant_trials tr ON tr.tenant_id=t.id ON CONFLICT(tenant_id) DO NOTHING;
